{"implementation":"def solve(case):
    import json
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])

    # Build node lookup and children map
    node_by_id = {}
    children = {}
    for n in nodes:
        nid = n['id']
        if nid in node_by_id:
            raise ValueError(f"Duplicate node id: {nid}")
        node_by_id[nid] = n
        parent = n.get('parent')
        if parent is not None:
            children.setdefault(parent, []).append(nid)

    # Validate root
    if 'root' not in node_by_id:
        raise ValueError("Missing root node")
    if node_by_id['root']['parent'] is not None:
        raise ValueError("Root must have null parent")
    # Validate all parent references exist
    for n in nodes:
        p = n.get('parent')
        if p is not None and p not in node_by_id:
            raise ValueError(f"Parent {p} not found for node {n['id']}")
    # Validate required symbols exist in tree
    all_symbols = {n['symbol'] for n in nodes}
    for s in required_symbols:
        if s not in all_symbols:
            raise ValueError(f"Required symbol {s} not present in tree")

    # Initial retained set
    retained = set(node_by_id.keys())

    # Sort nodes by depth descending, then by id ascending (stable tie-break)
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    removal_order = []
    for n in sorted_nodes:
        nid = n['id']
        # Never remove root, required symbol node, or non-removable
        if nid == 'root' or n['symbol'] in required_symbols:
            continue
        if not n['removable']:
            continue
        # Must have no retained children
        has_retained_children = any(cid in retained for cid in children.get(nid, []))
        if has_retained_children:
            continue
        # Tentative removal: all required symbols must remain represented
        # (already ensured by not removing required symbol nodes)
        retained.remove(nid)
        removal_order.append(nid)

    retained_ids = sorted(retained)
    return {
        'retained_ids': retained_ids,
        'removal_order': removal_order
    }"}
